import{_ as a,c as s,o as t,ag as e}from"./chunks/framework.CMajxlqO.js";const g=JSON.parse('{"title":"Enkla logiska funktioner","description":"","frontmatter":{},"headers":[],"relativePath":"04-programmering/logiska-funktioner.md","filePath":"04-programmering/logiska-funktioner.md","lastUpdated":1768316137000}'),p={name:"04-programmering/logiska-funktioner.md"};function l(i,n,o,r,d,c){return t(),s("div",null,[...n[0]||(n[0]=[e(`<h1 id="enkla-logiska-funktioner" tabindex="-1">Enkla logiska funktioner <a class="header-anchor" href="#enkla-logiska-funktioner" aria-label="Permalink to &quot;Enkla logiska funktioner&quot;">​</a></h1><p>Grunden i all PLC-programmering är logiska funktioner. Här lär du dig de mest grundläggande operationerna som används i nästan varje PLC-program: AND, OR, NOT, timers, counters och Set/Reset-logik.</p><h2 id="grundlaggande-logiska-operationer" tabindex="-1">Grundläggande logiska operationer <a class="header-anchor" href="#grundlaggande-logiska-operationer" aria-label="Permalink to &quot;Grundläggande logiska operationer&quot;">​</a></h2><h3 id="and-operation" tabindex="-1">AND-operation <a class="header-anchor" href="#and-operation" aria-label="Permalink to &quot;AND-operation&quot;">​</a></h3><p>AND-operation ger TRUE endast när <strong>alla</strong> ingångar är TRUE.</p><p><strong>Sanningstabell:</strong></p><table tabindex="0"><thead><tr><th>A</th><th>B</th><th>A AND B</th></tr></thead><tbody><tr><td>0</td><td>0</td><td>0</td></tr><tr><td>0</td><td>1</td><td>0</td></tr><tr><td>1</td><td>0</td><td>0</td></tr><tr><td>1</td><td>1</td><td>1</td></tr></tbody></table><p><strong>LAD-exempel:</strong></p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---| Input_A |---| Input_B |---( Output )---</span></span></code></pre></div><p><strong>SCL-exempel:</strong></p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Output := Input_A AND Input_B;</span></span></code></pre></div><p><strong>Praktiskt exempel:</strong> Motor startar endast om både startknapp är tryckt OCH inget larm är aktivt.</p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Motor_Start := Start_Button AND NOT Alarm;</span></span></code></pre></div><h3 id="or-operation" tabindex="-1">OR-operation <a class="header-anchor" href="#or-operation" aria-label="Permalink to &quot;OR-operation&quot;">​</a></h3><p>OR-operation ger TRUE när <strong>minst en</strong> ingång är TRUE.</p><p><strong>Sanningstabell:</strong></p><table tabindex="0"><thead><tr><th>A</th><th>B</th><th>A OR B</th></tr></thead><tbody><tr><td>0</td><td>0</td><td>0</td></tr><tr><td>0</td><td>1</td><td>1</td></tr><tr><td>1</td><td>0</td><td>1</td></tr><tr><td>1</td><td>1</td><td>1</td></tr></tbody></table><p><strong>LAD-exempel (parallellkoppling):</strong></p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>      | Input_A |</span></span>
<span class="line"><span>------|         |------( Output )---</span></span>
<span class="line"><span>      | Input_B |</span></span></code></pre></div><p><strong>SCL-exempel:</strong></p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Output := Input_A OR Input_B;</span></span></code></pre></div><p><strong>Praktiskt exempel:</strong> Larm aktiveras om ANTINGEN övertemperatur ELLER övertryck detekteras.</p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Alarm := (Temperature &gt; Max_Temp) OR (Pressure &gt; Max_Pressure);</span></span></code></pre></div><h3 id="not-operation-invertering" tabindex="-1">NOT-operation (invertering) <a class="header-anchor" href="#not-operation-invertering" aria-label="Permalink to &quot;NOT-operation (invertering)&quot;">​</a></h3><p>NOT-operation <strong>inverterar</strong> ett värde: TRUE blir FALSE, FALSE blir TRUE.</p><p><strong>Sanningstabell:</strong></p><table tabindex="0"><thead><tr><th>A</th><th>NOT A</th></tr></thead><tbody><tr><td>0</td><td>1</td></tr><tr><td>1</td><td>0</td></tr></tbody></table><p><strong>LAD-exempel (normalt stängd kontakt):</strong></p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---|/Emergency_Stop/|---( Motor_Enable )---</span></span></code></pre></div><p><strong>SCL-exempel:</strong></p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Motor_Enable := NOT Emergency_Stop;</span></span></code></pre></div><p><strong>Praktiskt exempel:</strong> Motor kör så länge nödstoppknappen INTE är tryckt.</p><h3 id="xor-operation-exklusiv-or" tabindex="-1">XOR-operation (exklusiv OR) <a class="header-anchor" href="#xor-operation-exklusiv-or" aria-label="Permalink to &quot;XOR-operation (exklusiv OR)&quot;">​</a></h3><p>XOR ger TRUE när ingångarna har <strong>olika</strong> värden.</p><p><strong>Sanningstabell:</strong></p><table tabindex="0"><thead><tr><th>A</th><th>B</th><th>A XOR B</th></tr></thead><tbody><tr><td>0</td><td>0</td><td>0</td></tr><tr><td>0</td><td>1</td><td>1</td></tr><tr><td>1</td><td>0</td><td>1</td></tr><tr><td>1</td><td>1</td><td>0</td></tr></tbody></table><p><strong>SCL-exempel:</strong></p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Output := Input_A XOR Input_B;</span></span></code></pre></div><p><strong>Praktiskt exempel:</strong> Larm när endast EN av två sensorer detekterar produkt (felaktig detektion).</p><h2 id="sjalvhallning-latching" tabindex="-1">Självhållning (Latching) <a class="header-anchor" href="#sjalvhallning-latching" aria-label="Permalink to &quot;Självhållning (Latching)&quot;">​</a></h2><p>Självhållning gör att en utgång behåller sitt tillstånd tills den explicit nollställs.</p><h3 id="lad-med-sjalvhallning" tabindex="-1">LAD med självhållning <a class="header-anchor" href="#lad-med-sjalvhallning" aria-label="Permalink to &quot;LAD med självhållning&quot;">​</a></h3><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Network 1: Start/Stop med självhållning</span></span>
<span class="line"><span>          Start_Button     Motor_Running      Stop_Button</span></span>
<span class="line"><span>---| |-------------||-----------| / |--------( Motor_Running )---</span></span></code></pre></div><p><strong>Förklaring:</strong></p><ol><li>Start_Button startar motorn (sätter Motor_Running = TRUE)</li><li>Motor_Running håller sig själv aktiv via parallellkoppling</li><li>Stop_Button bryter kretsen (nollställer Motor_Running)</li></ol><h3 id="scl-med-sjalvhallning" tabindex="-1">SCL med självhållning <a class="header-anchor" href="#scl-med-sjalvhallning" aria-label="Permalink to &quot;SCL med självhållning&quot;">​</a></h3><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Start-logik</span></span>
<span class="line"><span>IF Start_Button AND NOT Stop_Button THEN</span></span>
<span class="line"><span>    Motor_Running := TRUE;</span></span>
<span class="line"><span>END_IF;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Stopp-logik</span></span>
<span class="line"><span>IF Stop_Button THEN</span></span>
<span class="line"><span>    Motor_Running := FALSE;</span></span>
<span class="line"><span>END_IF;</span></span></code></pre></div><h3 id="set-reset-instruktioner" tabindex="-1">Set/Reset-instruktioner <a class="header-anchor" href="#set-reset-instruktioner" aria-label="Permalink to &quot;Set/Reset-instruktioner&quot;">​</a></h3><p>TIA Portal har dedikerade Set- och Reset-instruktioner:</p><p><strong>LAD:</strong></p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Network 1: Set motor</span></span>
<span class="line"><span>---| Start_Button |---(S Motor_Running)---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Network 2: Reset motor</span></span>
<span class="line"><span>---| Stop_Button |---(R Motor_Running)---</span></span></code></pre></div><p><strong>SCL med SR flipflop:</strong></p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;SR_Motor&quot;(</span></span>
<span class="line"><span>    S1 := Start_Button,</span></span>
<span class="line"><span>    R := Stop_Button</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span>Motor_Running := &quot;SR_Motor&quot;.Q1;</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Prioritet</p><p>Om både Set och Reset är aktiva samtidigt, avgör ordningen i programmet vad som händer. Vanligtvis ges Reset högre prioritet (säkerhet).</p></div><h2 id="timers-tidur" tabindex="-1">Timers (Tidur) <a class="header-anchor" href="#timers-tidur" aria-label="Permalink to &quot;Timers (Tidur)&quot;">​</a></h2><p>Timers är avgörande för att skapa fördröjningar och tidssekvenser.</p><h3 id="ton-timer-on-delay" tabindex="-1">TON - Timer On-Delay <a class="header-anchor" href="#ton-timer-on-delay" aria-label="Permalink to &quot;TON - Timer On-Delay&quot;">​</a></h3><p>TON aktiverar utgången efter en <strong>fördröjning</strong>.</p><p><strong>Beteende:</strong></p><ul><li>Input = TRUE → Timer börjar räkna</li><li>Efter PT-tid → Output = TRUE</li><li>Input = FALSE → Timer nollställs, Output = FALSE</li></ul><p><strong>LAD-exempel:</strong></p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Network 1: Fördröjd start</span></span>
<span class="line"><span>           ┌──────────────┐</span></span>
<span class="line"><span>---| Start |----┤ TON          ├--- Motor_Delayed</span></span>
<span class="line"><span>           │ IN    Q  OUT  │</span></span>
<span class="line"><span>  T#5s     │ PT    ET      │</span></span>
<span class="line"><span>-----------┤               │</span></span>
<span class="line"><span>           └──────────────┘</span></span></code></pre></div><p><strong>SCL-exempel:</strong></p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;Delay_Timer&quot;(</span></span>
<span class="line"><span>    IN := Start_Button,</span></span>
<span class="line"><span>    PT := T#5S</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span>Motor_Delayed := &quot;Delay_Timer&quot;.Q;</span></span></code></pre></div><p><strong>Praktiskt exempel:</strong> Fördröjd motorstart för mjukstart.</p><h3 id="tof-timer-off-delay" tabindex="-1">TOF - Timer Off-Delay <a class="header-anchor" href="#tof-timer-off-delay" aria-label="Permalink to &quot;TOF - Timer Off-Delay&quot;">​</a></h3><p>TOF håller utgången aktiv en stund efter att ingången släckts.</p><p><strong>Beteende:</strong></p><ul><li>Input = TRUE → Output = TRUE omedelbart</li><li>Input = FALSE → Timer börjar räkna</li><li>Efter PT-tid → Output = FALSE</li></ul><p><strong>SCL-exempel:</strong></p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;Off_Delay_Timer&quot;(</span></span>
<span class="line"><span>    IN := Presence_Sensor,</span></span>
<span class="line"><span>    PT := T#30S</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span>Light_Output := &quot;Off_Delay_Timer&quot;.Q;</span></span></code></pre></div><p><strong>Praktiskt exempel:</strong> Belysning som stannar på 30 sekunder efter att någon lämnat rummet.</p><h3 id="tp-timer-pulse" tabindex="-1">TP - Timer Pulse <a class="header-anchor" href="#tp-timer-pulse" aria-label="Permalink to &quot;TP - Timer Pulse&quot;">​</a></h3><p>TP genererar en puls med fix längd.</p><p><strong>Beteende:</strong></p><ul><li>Positiv flank på Input → Output = TRUE i PT-tid</li><li>Output = FALSE efter PT-tid</li><li>Nya pulser under pågående puls ignoreras</li></ul><p><strong>SCL-exempel:</strong></p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;Pulse_Timer&quot;(</span></span>
<span class="line"><span>    IN := Trigger_Button,</span></span>
<span class="line"><span>    PT := T#2S</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span>Valve_Pulse := &quot;Pulse_Timer&quot;.Q;</span></span></code></pre></div><p><strong>Praktiskt exempel:</strong> Kortvarig öppning av ventil vid knapptryck.</p><h3 id="tonr-timer-on-delay-retentive" tabindex="-1">TONR - Timer On-Delay Retentive <a class="header-anchor" href="#tonr-timer-on-delay-retentive" aria-label="Permalink to &quot;TONR - Timer On-Delay Retentive&quot;">​</a></h3><p>TONR är en ackumulerande timer som behåller sin tid mellan avbrott.</p><p><strong>SCL-exempel:</strong></p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;Accumulating_Timer&quot;(</span></span>
<span class="line"><span>    IN := Motor_Running,</span></span>
<span class="line"><span>    R := Reset_Timer,</span></span>
<span class="line"><span>    PT := T#100H</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span>Maintenance_Due := &quot;Accumulating_Timer&quot;.Q;</span></span></code></pre></div><p><strong>Praktiskt exempel:</strong> Totaltid för motoranvändning, för underhållsplanering.</p><h2 id="counters-raknare" tabindex="-1">Counters (Räknare) <a class="header-anchor" href="#counters-raknare" aria-label="Permalink to &quot;Counters (Räknare)&quot;">​</a></h2><p>Counters används för att räkna händelser.</p><h3 id="ctu-count-up" tabindex="-1">CTU - Count Up <a class="header-anchor" href="#ctu-count-up" aria-label="Permalink to &quot;CTU - Count Up&quot;">​</a></h3><p>CTU räknar uppåt.</p><p><strong>LAD-exempel:</strong></p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Network 1: Räkna produkter</span></span>
<span class="line"><span>           ┌──────────────┐</span></span>
<span class="line"><span>---| Sensor |---┤ CTU          ├--- Batch_Complete</span></span>
<span class="line"><span>           │ CU    Q  OUT  │</span></span>
<span class="line"><span>---| Reset  |---┤ R     CV      ├--- Current_Count</span></span>
<span class="line"><span>           │ PV           │</span></span>
<span class="line"><span>  100      -----┤               │</span></span>
<span class="line"><span>           └──────────────┘</span></span></code></pre></div><p><strong>SCL-exempel:</strong></p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;Product_Counter&quot;(</span></span>
<span class="line"><span>    CU := Product_Sensor,  // Räkna vid positiv flank</span></span>
<span class="line"><span>    R := Reset_Counter,</span></span>
<span class="line"><span>    PV := 100</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span>Batch_Complete := &quot;Product_Counter&quot;.Q;</span></span>
<span class="line"><span>Current_Count := &quot;Product_Counter&quot;.CV;</span></span></code></pre></div><p><strong>Praktiskt exempel:</strong> Räkna 100 produkter, sedan stoppa produktionen.</p><h3 id="ctd-count-down" tabindex="-1">CTD - Count Down <a class="header-anchor" href="#ctd-count-down" aria-label="Permalink to &quot;CTD - Count Down&quot;">​</a></h3><p>CTD räknar neråt.</p><p><strong>SCL-exempel:</strong></p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;Countdown_Counter&quot;(</span></span>
<span class="line"><span>    CD := Dispense_Pulse,  // Räkna ner vid varje puls</span></span>
<span class="line"><span>    LOAD := Load_Counter,</span></span>
<span class="line"><span>    PV := 50</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span>Empty := &quot;Countdown_Counter&quot;.Q;  // TRUE när CV &lt;= 0</span></span></code></pre></div><p><strong>Praktiskt exempel:</strong> Räkna ner antal kvarvarande enheter i magasin.</p><h3 id="ctud-count-up-down" tabindex="-1">CTUD - Count Up/Down <a class="header-anchor" href="#ctud-count-up-down" aria-label="Permalink to &quot;CTUD - Count Up/Down&quot;">​</a></h3><p>CTUD kombinerar upp- och nedräkning.</p><p><strong>SCL-exempel:</strong></p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;Updown_Counter&quot;(</span></span>
<span class="line"><span>    CU := Entry_Sensor,    // Räkna upp när någon går in</span></span>
<span class="line"><span>    CD := Exit_Sensor,     // Räkna ner när någon går ut</span></span>
<span class="line"><span>    R := Reset_Counter,</span></span>
<span class="line"><span>    LOAD := FALSE,</span></span>
<span class="line"><span>    PV := 0</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span>People_Inside := &quot;Updown_Counter&quot;.CV;</span></span>
<span class="line"><span>Max_Reached := &quot;Updown_Counter&quot;.QU;  // TRUE när CV &gt;= PV</span></span></code></pre></div><p><strong>Praktiskt exempel:</strong> Räkna antal personer i ett rum.</p><h2 id="flanktriggning-edge-detection" tabindex="-1">Flanktriggning (Edge Detection) <a class="header-anchor" href="#flanktriggning-edge-detection" aria-label="Permalink to &quot;Flanktriggning (Edge Detection)&quot;">​</a></h2><p>Flankdetektering används för att trigga en händelse vid signaländring.</p><h3 id="p-trig-positive-edge-stigande-flank" tabindex="-1">P_TRIG - Positive Edge (Stigande flank) <a class="header-anchor" href="#p-trig-positive-edge-stigande-flank" aria-label="Permalink to &quot;P_TRIG - Positive Edge (Stigande flank)&quot;">​</a></h3><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;Edge_Detect&quot;(</span></span>
<span class="line"><span>    CLK := Button_Input</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span>IF &quot;Edge_Detect&quot;.Q THEN</span></span>
<span class="line"><span>    Counter := Counter + 1;  // Räkna endast vid knapptryck (inte när knapp hålls ned)</span></span>
<span class="line"><span>END_IF;</span></span></code></pre></div><h3 id="n-trig-negative-edge-fallande-flank" tabindex="-1">N_TRIG - Negative Edge (Fallande flank) <a class="header-anchor" href="#n-trig-negative-edge-fallande-flank" aria-label="Permalink to &quot;N_TRIG - Negative Edge (Fallande flank)&quot;">​</a></h3><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;Falling_Edge&quot;(</span></span>
<span class="line"><span>    CLK := Signal_Input</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span>IF &quot;Falling_Edge&quot;.Q THEN</span></span>
<span class="line"><span>    // Utför något vid signalens fallande flank</span></span>
<span class="line"><span>END_IF;</span></span></code></pre></div><h2 id="praktiskt-exempel-komplett-motorstyrning" tabindex="-1">Praktiskt exempel: Komplett motorstyrning <a class="header-anchor" href="#praktiskt-exempel-komplett-motorstyrning" aria-label="Permalink to &quot;Praktiskt exempel: Komplett motorstyrning&quot;">​</a></h2><p>Kombinera flera logiska funktioner:</p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Flanktriggning för start/stopp-knappar</span></span>
<span class="line"><span>&quot;Start_Edge&quot;(CLK := Start_Button);</span></span>
<span class="line"><span>&quot;Stop_Edge&quot;(CLK := Stop_Button);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Självhållning med prioritet för stopp</span></span>
<span class="line"><span>IF &quot;Start_Edge&quot;.Q AND NOT Emergency_Stop THEN</span></span>
<span class="line"><span>    Motor_Enable := TRUE;</span></span>
<span class="line"><span>END_IF;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>IF &quot;Stop_Edge&quot;.Q OR Emergency_Stop THEN</span></span>
<span class="line"><span>    Motor_Enable := FALSE;</span></span>
<span class="line"><span>END_IF;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Fördröjd start (mjukstart)</span></span>
<span class="line"><span>&quot;Start_Delay&quot;(</span></span>
<span class="line"><span>    IN := Motor_Enable,</span></span>
<span class="line"><span>    PT := T#2S</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Motor output</span></span>
<span class="line"><span>Motor_Output := &quot;Start_Delay&quot;.Q AND NOT Overload_Alarm;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Körtidsräknare (för underhåll)</span></span>
<span class="line"><span>&quot;Runtime_Counter&quot;(</span></span>
<span class="line"><span>    IN := Motor_Output,</span></span>
<span class="line"><span>    R := FALSE,</span></span>
<span class="line"><span>    PT := T#500H</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span>Maintenance_Due := &quot;Runtime_Counter&quot;.Q;</span></span></code></pre></div><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h2><p>✅ <strong>Använd beskrivande namn</strong> - <code>Motor_Start</code> istället för <code>M0.0</code> ✅ <strong>Dokumentera komplexa villkor</strong> - Kommentarer i koden ✅ <strong>Prioritera säkerhet</strong> - Emergency Stop ska alltid ha högst prioritet ✅ <strong>Testa flanktriggring</strong> - Använd P_TRIG/N_TRIG för knappar ✅ <strong>Timeout-skydd</strong> - Använd timers för att detektera fastnade processer</p><h2 id="resurser-och-dokumentation" tabindex="-1">Resurser och dokumentation <a class="header-anchor" href="#resurser-och-dokumentation" aria-label="Permalink to &quot;Resurser och dokumentation&quot;">​</a></h2><h3 id="officiell-dokumentation" tabindex="-1">Officiell dokumentation <a class="header-anchor" href="#officiell-dokumentation" aria-label="Permalink to &quot;Officiell dokumentation&quot;">​</a></h3><ul><li><a href="https://support.industry.siemens.com/cs/document/36932465" target="_blank" rel="noreferrer">S7-1200 Instruction List</a> - Alla instruktioner</li><li><a href="https://support.industry.siemens.com/cs/ww/en/view/90885040" target="_blank" rel="noreferrer">Programming Guideline</a> - Best practices</li><li><a href="https://support.industry.siemens.com/cs/document/109476369" target="_blank" rel="noreferrer">Timers and Counters</a> - Timer/counter manual</li></ul><h3 id="video-tutorials" tabindex="-1">Video-tutorials <a class="header-anchor" href="#video-tutorials" aria-label="Permalink to &quot;Video-tutorials&quot;">​</a></h3><ul><li>YouTube: &quot;TIA Portal timers tutorial&quot;</li><li>YouTube: &quot;TIA Portal counters tutorial&quot;</li><li>YouTube: &quot;TIA Portal logic functions LAD&quot;</li><li>YouTube: &quot;TIA Portal edge detection&quot;</li></ul><div class="tip custom-block"><p class="custom-block-title">Nästa steg</p><p>Nu när du behärskar logiska funktioner, lär dig arbeta med <a href="./../05-taggar/globala-lokala.html">Taggar och datatyper</a> för att organisera dina variabler effektivt!</p></div>`,120)])])}const h=a(p,[["render",l]]);export{g as __pageData,h as default};
